using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Text;
using System.Web.Script.Serialization;

internal static class EnemyTargetVerification {
    static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
    static void Var(List<byte> b,uint v){do{byte n=(byte)(v&127);v>>=7;b.Add((byte)(n|(v!=0?128:0)));}while(v!=0);}
    internal static byte[] Player(uint actor,string name,uint hp,uint max,bool own){var b=new List<byte>{own?(byte)0x33:(byte)0x45,0x36};Var(b,actor);b.AddRange(new byte[]{0x15,0xb0,0xa0,1,7});var n=Encoding.UTF8.GetBytes(name);b.Add((byte)n.Length);b.AddRange(n);if(own)b.AddRange(new byte[]{0x15,5});int at=b.Count;b.AddRange(BitConverter.GetBytes(26u));b.Add(1);while(b.Count<at+(own?160:6))b.Add(0);b.AddRange(new byte[2]);foreach(float f in new[]{93000f,27000f,26000f,0f})b.AddRange(BitConverter.GetBytes(f));b.AddRange(new byte[2]);b.Add(1);Var(b,hp);Var(b,max);b.AddRange(BitConverter.GetBytes(4591u));b.AddRange(BitConverter.GetBytes(4591u));b.AddRange(new byte[44]);while(b.Count<128)b.Add(0);var result=b.ToArray();if(own)Array.Copy(BitConverter.GetBytes(45u),0,result,at+5,4);return result;}
    static byte[] Focus(uint actor,uint target){var b=new List<byte>{0x35,0x38};Var(b,actor);b.Add(0);Var(b,target);return b.ToArray();}
    static byte[] Hp(uint actor,uint hp){var b=new List<byte>{0,0x8d};Var(b,actor);b.AddRange(new byte[]{2,1,0});b.AddRange(BitConverter.GetBytes((long)hp));return b.ToArray();}
    static void Feed(EnemyTargetSignal signal,byte[] b,double t,string flow="A"){signal.Consume(b,0,b.Length,t,flow);}
    static byte[] LongerHeader(byte[] source,int at,int extra=1){var b=new byte[source.Length+extra];Buffer.BlockCopy(source,0,b,0,at);for(int n=0;n<extra;n++)b[at+n]=1;Buffer.BlockCopy(source,at,b,at+extra,source.Length-at);return b;}
    static void VerifyProfileLayouts(){
        foreach(bool own in new[]{false,true}){
            var normal=Player(2024,"ProfileProbe",10000,12000,own);EnemyTargetSignal.Player legacy,extended;
            Check(EnemyTargetSignal.PlayerState(normal,0,normal.Length,own,out legacy),"Original profile remains supported");var longer=LongerHeader(normal,legacy.StateOffset);
            Check(EnemyTargetSignal.PlayerState(longer,0,longer.Length,own,out extended)&&extended.Actor==legacy.Actor&&extended.Current==10000&&extended.Maximum==12000&&extended.Mana==legacy.Mana&&extended.ManaMaximum==legacy.ManaMaximum&&extended.StateOffset==legacy.StateOffset+1,"One-byte longer own/remote header reads explicit resources at the validated boundary");
            int boundary=extended.StateOffset;for(int n=0;n<boundary+20;n++)Check(!EnemyTargetSignal.PlayerState(longer,0,n,own,out extended),"Truncated profile cannot supply a resource maximum");
            var unsupported=LongerHeader(normal,legacy.StateOffset,3);Check(!EnemyTargetSignal.PlayerState(unsupported,0,unsupported.Length,own,out extended),"Unknown longer header is rejected instead of scanning for plausible HP");
            if(own){int level;EnemyDetailReader.Position position;Check(EnemyDetailReader.Character(longer,0,longer.Length,out level,out position)&&level==45&&position.Known&&position.X==93000&&position.Y==27000&&position.Z==26000,"Character position uses the same validated state boundary as resources");}
        }
        // Both supported offsets can be made numerically plausible. The reader
        // must report unknown rather than choose whichever looks convenient.
        var ambiguous=Player(2024,"Ambiguous",1,1,true);EnemyTargetSignal.Player known;Check(EnemyTargetSignal.PlayerState(ambiguous,0,ambiguous.Length,true,out known),"Ambiguity fixture baseline");int values=known.StateOffset+23;Buffer.BlockCopy(BitConverter.GetBytes(1u),0,ambiguous,values,4);Buffer.BlockCopy(BitConverter.GetBytes(256u),0,ambiguous,values+4,4);Array.Resize(ref ambiguous,ambiguous.Length+1);Check(!EnemyTargetSignal.PlayerState(ambiguous,0,ambiguous.Length,true,out known),"Ambiguous resource boundaries must fail closed");
    }
    static void VerifyScale(){var original=new EnergyConfiguration{Options=new EnergyBarOptions(),Bounds=new Rectangle(100,200,320,4)};for(int kind=0;kind<4;kind++){var c=original.Copy();var b=ProgressWidgetScale.Bar(c,kind);int originalText=b.TextSize;for(int pct=105;pct<=200;pct+=5)ProgressWidgetScale.Apply(c,kind,pct);Check(b.TextSize==originalText*2,"Incremental scale preserves unrounded text growth");if(kind==1)Check(c.Stagger.Countdown.FontSize==original.Stagger.Countdown.FontSize*2,"Countdown scales with bar");if(kind>=2)Check((kind==2?c.EnemyHealth:c.EnemyTarget).Name.FontSize==(kind==2?original.EnemyHealth:original.EnemyTarget).Name.FontSize*2,"Name scales with bar");ProgressWidgetScale.Apply(c,kind,100);Check(b.TextSize==originalText,"Scale round-trip restores baseline");if(kind==0)Check(c.Bounds==original.Bounds,"Scale preserves anchor and dimensions round trip");var clone=c.Copy();clone.Options.ScaleReference=null;Check(c.Options.ScaleReference!=null||kind!=0,"Reference is independently copied");b.TextSize=30;ProgressWidgetScale.Apply(c,kind,200);Check(b.TextSize==60,"Manual text edits establish fresh scale reference");}var json=new JavaScriptSerializer();var value=original.Copy();ProgressWidgetScale.Apply(value,3,150);var saved=EnemyHealthOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{enemyTarget=value.EnemyTarget})),"enemyTarget");Check(saved.Bar.ScalePercent==150&&saved.Bar.ScaleReference!=null,"Scale reference persistence");var copy=saved.Copy();copy.Bar.ScaleReference.Width=1;Check(saved.Bar.ScaleReference.Width!=1,"Scale reference deep copy");}
    static void VerifyRefreshAtCapacity(){var signal=new EnemyTargetSignal();signal.Configure(true);var source=new EnemyHealthSignal();double t=DpsHistory.UtcNow();Feed(signal,Player(1923,"LocalProbe",11000,12013,true),t);Feed(signal,Player(2024,"KeepTarget",8000,9000,false),t);for(uint n=0;n<254;n++)Feed(signal,Player(3000+n,"Crowd"+n,8000,9000,false),t+1+n*.001);Feed(signal,Focus(111,2024),t+2);var enemy=new EnemyHealthSignal.Sample{Actor=111,Current=100,Maximum=100,Flow="A",Traffic=t+2};Check(signal.Read(enemy,source)!=null,"Focus target is retained at player quota");for(int n=0;n<30;n++)Feed(signal,Player(3253,"Crowd253",8000,9000,false),t+3+n*.001);Check(signal.Read(enemy,source)!=null&&signal.Read(enemy,source).Actor==2024,"Refreshing an existing player cannot evict a different target-of-target profile");}
    internal static void Run(string root){VerifyProfileLayouts();VerifyRefreshAtCapacity();
        VerifyScale();var signal=new EnemyTargetSignal();var source=new EnemyHealthSignal();signal.Configure(true);double t=DpsHistory.UtcNow();var enemy=new EnemyHealthSignal.Sample{Actor=111,Current=100,Maximum=100,Flow="A",Time=t,Traffic=t};
        Feed(signal,Focus(111,1923),t);Check(signal.Read(enemy,source)==null,"Focus without confirmed health must remain hidden");
        Feed(signal,Player(1923,"Charlotta",11000,12013,true),t);var s=signal.Read(enemy,source);Check(s!=null&&s.Name=="Charlotta"&&s.Current==11000&&s.Maximum==12013&&s.IsSelf,"Own explicit damaged HP and maximum");
        Feed(signal,Player(2024,"Edeln",8000,9000,false),t);Feed(signal,Focus(111,2024),t+1);s=signal.Read(enemy,source);Check(s!=null&&s.Actor==2024&&s.Name=="Edeln"&&s.Maximum==9000&&!s.IsSelf,"Enemy focus change selects another character");
        Feed(signal,Hp(2024,4500),t+2);Check(signal.Read(enemy,source).Current==4500,"Remote health update");Feed(signal,Hp(2024,0),t+3);Check(!EnemyHealthSignal.Fresh(signal.Read(enemy,source),t+3),"Dead target not displayed");Feed(signal,Hp(2024,7000),t+4);
        Feed(signal,Hp(2024,1000),t+3);Check(signal.Read(enemy,source).Current==7000,"Older health update cannot overwrite current state");
        Feed(signal,Focus(111,1923),t+4,"B");Check(signal.Read(enemy,source).Actor==2024,"Flow isolation");Feed(signal,Focus(111,0),t+5);Check(signal.Read(enemy,source)==null,"Cleared focus hides");
        Feed(signal,Focus(111,1923),t+6);enemy.Current=0;Check(signal.Read(enemy,source)==null,"Enemy death hides target-of-target");enemy.Current=100;enemy.Traffic=t-11;Check(signal.Read(enemy,source)==null,"Stale enemy hides target-of-target");enemy.Traffic=t;
        EnemyTargetSignal.Player p;var invalid=Player(3030,"Unknown",500,100,false);Check(!EnemyTargetSignal.PlayerState(invalid,0,invalid.Length,false,out p),"Reject health above maximum");var full=Player(1923,"Charlotta",11000,12013,true);for(int i=0;i<full.Length;i++)Check(!EnemyTargetSignal.PlayerState(full,0,i,true,out p),"Reject truncated profile");
        var random=new Random(87);for(int i=0;i<3000;i++){var b=new byte[random.Next(2,380)];random.NextBytes(b);int[] ops={0x3336,0x4536,0x3538,0x008d,0x1b92};int op=ops[i%ops.Length];b[0]=(byte)(op>>8);b[1]=(byte)op;Feed(signal,b,t+i*.00001);}
        signal.Reset();Check(signal.Read(enemy,source)==null,"Transport reset clears focus and profiles");signal.Configure(false);Feed(signal,full,t);Feed(signal,Focus(111,1923),t);Check(signal.Read(enemy,source)==null,"Disabled reader ignores profiles");
        var options=EnemyHealthOptions.TargetDefaults();Check(!options.Bar.CurrentText&&!options.Bar.MaximumText&&!options.Bar.PercentageText&&!options.Name.Marker&&options.Bar.MediumColor=="#3D9FCE","Simple blue preset with name only");options.SelfNameColor="#FFD8BD";var copy=options.Copy();copy.Name.FontSize=22;Check(options.Name.FontSize==14,"Independent name copy");var json=new JavaScriptSerializer();var saved=EnemyHealthOptions.Read(json.Deserialize<Dictionary<string,object>>(json.Serialize(new{enemyTarget=copy})),"enemyTarget");Check(saved.Name.FontSize==22&&saved.SelfNameColor=="#FFD8BD"&&!saved.Name.Marker&&!saved.Bar.PercentageText,"Target configuration persistence");
        var appearance=options.Copy();appearance.SelfHighlight=true;appearance.SelfColor="#EF986B";var local=appearance.Copy();local.Name.Color=local.SelfNameColor;local.Bar.DynamicColors=false;local.Bar.LowColor=local.Bar.MediumColor=local.Bar.HighColor=local.SelfColor;Check(EnemyTargetSignal.PlayerState(Player(2024,"Edeln",8000,9000,false),0,Player(2024,"Edeln",8000,9000,false).Length,false,out p)&&p.Actor==2024,"Remote profile independent from local identity");
        Directory.CreateDirectory(Path.Combine(root,"designs"));using(var bitmap=EnemyHealthOverlay.RenderPreview(320,.65,options,new BarDesign.GlowWorkspace(),"es",true))bitmap.Save(Path.Combine(root,"designs","enemy-target-preview.png"));
        using(var canvas=new Bitmap(700,260))using(var g=Graphics.FromImage(canvas)){g.Clear(Color.FromArgb(22,29,33));for(int pct=100;pct<=200;pct+=50){var config=new EnergyConfiguration{Options=new EnergyBarOptions(),Bounds=new Rectangle(0,0,320,4)};config.EnemyTarget=appearance.Copy();ProgressWidgetScale.Apply(config,3,pct);using(var bar=EnemyHealthOverlay.RenderPreview(config.EnemyTarget.Bounds.Width,.65,config.EnemyTarget,new BarDesign.GlowWorkspace(),"es",true))g.DrawImageUnscaled(bar,12,15+(pct-100)*1); }canvas.Save(Path.Combine(root,"designs","enemy-target-scale-preview.png"));}using(var own=EnemyHealthOverlay.RenderPreview(320,.7,local,new BarDesign.GlowWorkspace(),"es",true))own.Save(Path.Combine(root,"designs","enemy-target-self-color-preview.png"));
        using(var owner=new EnergyOverlay(root,true)){var settings=new HelperSettings(owner);try{settings.VerifyEnemyTarget(root);settings.VerifyWholeBarScale(root);}finally{settings.Close();}}
        File.WriteAllText(Path.Combine(root,"enemy-target-test.txt"),"PASS: explicit own/remote current and maximum health; received enemy focus/change/clear; independent flow; death/freshness/reset; malformed/truncated profiles; name-only blue preset, independent preferences, rendering, whole scale on all four bars, incremental rounding/manual edits/persistence, self identity color and menu undo.");
    }
    internal static void Replay(string root,string frames){var json=new JavaScriptSerializer();int own=0,remote=0,focus=0,paired=0;var signal=new EnemyTargetSignal();signal.Configure(true);var source=new EnemyHealthSignal();double offset=double.NaN;foreach(var line in File.ReadLines(frames)){var row=json.Deserialize<Dictionary<string,object>>(line);string hex=Convert.ToString(row["hex"]);var b=new byte[hex.Length/2];for(int i=0;i<b.Length;i++)b[i]=Convert.ToByte(hex.Substring(i*2,2),16);double raw=Convert.ToDouble(row["ts"]);if(double.IsNaN(offset))offset=DpsHistory.UtcNow()-raw;double t=raw+offset;string flow=Convert.ToString(row["stream"]);Feed(signal,b,t,flow);int op=(b[0]<<8)|b[1];EnemyTargetSignal.Player p;if((op==0x3336||op==0x4536)&&EnemyTargetSignal.PlayerState(b,0,b.Length,op==0x3336,out p)){if(op==0x3336)own++;else remote++;}uint actor,target;if(op==0x3538&&EnemyTargetSignal.FocusFrame(b,0,b.Length,out actor,out target)){focus++;var enemy=new EnemyHealthSignal.Sample{Actor=actor,Current=1,Maximum=1,Flow=flow,Traffic=DpsHistory.UtcNow()};var s=signal.Read(enemy,source);if(s!=null&&s.Name!=null)paired++;}}Check(own>0&&remote>0&&focus>0&&paired>0,"Replay requires actual own/remote health profiles and matching NPC focus");File.WriteAllText(Path.Combine(root,"enemy-target-replay-test.txt"),"PASS: own profiles="+own+", remote profiles="+remote+", NPC focus frames="+focus+", paired with confirmed character health="+paired+". Does not establish universal aggro semantics.");}
}
